document.addEventListener("DOMContentLoaded", function () {
  const elementos = document.querySelectorAll('.encurta_description_related');
  const limiteCaracteres = 120;

  elementos.forEach(function (container) {
    const paragrafo = container.querySelector('p');
    if (paragrafo && paragrafo.textContent.length > limiteCaracteres) {
      const textoOriginal = paragrafo.textContent.trim();
      const textoCortado = textoOriginal.slice(0, limiteCaracteres).trimEnd() + '...';
      paragrafo.textContent = textoCortado;
    }
  });
});